<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
use FMonitor2\Tests\Support\{FixedPilotSessionClock,LengthQueuedPilotSessionEntropy,NativePilotSessionFilesystem,RecordingPilotSessionObserver};
spl_autoload_register(static function(string$class):void{$p='FMonitor\\IdentityAccess\\';if(str_starts_with($class,$p)){$f=dirname(__DIR__,2).'/app/IdentityAccess/'.substr($class,strlen($p)).'.php';if(is_file($f))require$f;}});assertSameValue(true,class_exists(FMonitor\IdentityAccess\PilotSessionStorageFactory::class),'INTENTIONAL_RED: v7 GC owner exists');require dirname(__DIR__).'/Support/PilotSessionStoragePublicApiFixture.php';
$parent=sys_get_temp_dir().'/fmonitor2-session-storage-tests';$root=$parent.'/task-'.bin2hex(random_bytes(8));$dir="$root/sessions/gcorder_v7";mkdir($dir,0700,true);chmod($root,0700);chmod("$root/sessions",0700);$remove=function(string$p)use(&$remove):void{if(is_link($p)||is_file($p)){unlink($p);return;}if(!is_dir($p))return;foreach(scandir($p)?:[]as$e)if($e!=='.'&&$e!=='..')$remove($p.'/'.$e);rmdir($p);};
try{$candidates=[];$baseTime=1_700_000_000;for($i=0;$i<101;$i++){$hash=hash('sha256',"gc-id-$i");$name=".revoked-$hash-".str_repeat(dechex($i%16),32).'.session';$path="$dir/$name";file_put_contents($path,"revoked-$i");chmod($path,0600);$mtime=$i===100?$baseTime-10:$baseTime;touch($path,$mtime);$lock="$dir/l-$hash.lock";file_put_contents($lock,'');chmod($lock,0600);touch($lock,$baseTime);$candidates[]=['name'=>$name,'mtime'=>$mtime,'digest'=>hash_file('sha256',$path)];}usort($candidates,static fn($a,$b)=>$a['mtime']<=>$b['mtime']?:strcmp($a['name'],$b['name']));$deleted=array_column(array_slice($candidates,0,100),'name');$remaining=$candidates[100]['name'];$owner=(new FMonitor\IdentityAccess\PilotSessionStorageFactory())->create(new FMonitor\IdentityAccess\PilotSessionStorageConfig($root,'gcorder_v7'),new NativePilotSessionFilesystem(),new FixedPilotSessionClock($baseTime+604801,1000),new LengthQueuedPilotSessionEntropy([32=>[str_repeat("\x51",32)]]),new RecordingPilotSessionObserver());$result=$owner->start(null);assertSameValue('OK',$result->status()->name,'bounded GC does not fail anonymous start');foreach($deleted as$name)assertSameValue(false,is_file("$dir/$name"),"oldest/binary selected $name");assertSameValue(true,is_file("$dir/$remaining"),'exact 101st candidate remains');assertSameValue(1,count(glob("$dir/.revoked-*.session")?:[]),'exactly 100 eligible artifacts deleted');assertSameValue(101,count(glob("$dir/l-*.lock")?:[]),'initially-associated locks not swept in same selection');$owner->close();echo"PASS: PILOT-SESSION-STORAGE-001 v7 GC oldest/binary limit\n";
}finally{$remove($root);if(is_dir($parent)&&count(scandir($parent)?:[])===2)rmdir($parent);}
